mapper.select:
select s.id, s.category, s.price, s.sort_order, null as resource_code, gc.group_code, gc.name, gc.color_url as image_url, gc.id as collect_id, s.item_desc from game_shop s join game_collect gc on s.item_id = gc.id where s.enabled = 1 and s.category = 2
and gc.group_code = #{groupCode}
order by s.sort_order asc, s.id asc limit #{offset}, #{limit}
